/* From Uiverse.io by TemRevil  - Tags: material design, neumorphism, glassmorphism, animation, subscription, button, hover, smooth */
.__UIV_SCOPE__ .button {
  position: relative;
  z-index: 1;
  padding: 10px 20px;
  background-color: transparent;
  color: #124;
  font-size: 28px;
  border: none;
  border-radius: 5px;
  transition: 0.15s 0s linear;
  cursor: pointer;
  overflow: hidden;
}
.__UIV_SCOPE__ .button:hover {
  color: #fff;
}
.__UIV_SCOPE__ .button:active {
  scale: 0.98;
}
.__UIV_SCOPE__ .b-hover {
  position: relative;
  bottom: -45px;
}
.__UIV_SCOPE__ .button:hover .b-hover {
  animation: b-a 0.2s linear forwards;
}

.__UIV_SCOPE__ .cir-1 {
  width: 100px;
  height: 100px;
  position: absolute;
  z-index: -6;
  left: -120px;
  bottom: -20px;
  background-color: #3395ffa1;
  border-radius: 50%;
}
.__UIV_SCOPE__ .button:hover .cir-1 {
  animation: cir-1-border 0.5s 0.3s linear forwards;
}
.__UIV_SCOPE__ .cir-2 {
  width: 100px;
  height: 100px;
  position: absolute;
  z-index: -2;
  left: -140px;
  bottom: -20px;
  background-color: #3358ffa1;
  border-radius: 50%;
}
.__UIV_SCOPE__ .cir-3 {
  width: 100px;
  height: 100px;
  position: absolute;
  z-index: -3;
  left: -160px;
  bottom: -20px;
  background-color: #6333ffa1;
  border-radius: 50%;
}
.__UIV_SCOPE__ .cir-4 {
  width: 100px;
  height: 100px;
  position: absolute;
  z-index: -4;
  left: -180px;
  bottom: -20px;
  background-color: #e433ffa1;
  border-radius: 50%;
}
.__UIV_SCOPE__ .cir-5 {
  width: 100px;
  height: 100px;
  position: absolute;
  z-index: -5;
  left: -200px;
  bottom: -20px;
  background-color: #ff33aab2;
  border-radius: 50%;
}
.__UIV_SCOPE__ .cir-6 {
  width: 100px;
  height: 100px;
  position: absolute;
  z-index: -6;
  left: -220px;
  bottom: -20px;
  background-color: #ff0084;
  border-radius: 50%;
}
.__UIV_SCOPE__ .button:hover .cir-6 {
  animation: cir-6-border 0.5s 0.3s linear forwards;
}
.__UIV_SCOPE__ .filter {
  animation: blur 0.6s 1s infinite linear alternate;
}
@keyframes b-a {
  0% {
    left: 0;
  }
  100% {
    left: 200px;
  }
}

@keyframes cir-1-border {
  0% {
    border-top-right-radius: 50%;
    border-bottom-right-radius: 50%;
  }
  100% {
    border-top-right-radius: 0px;
    border-bottom-right-radius: 0px;
  }
}
@keyframes cir-6-border {
  0% {
    border-top-left-radius: 50%;
    border-bottom-left-radius: 50%;
  }
  100% {
    border-top-left-radius: 0px;
    border-bottom-left-radius: 0px;
  }
}

@keyframes blur {
  0% {
    filter: none;
  }
  100% {
    filter: blur(3px);
  }
}
